import pandas as pd
O='/home/user/revi/FINAL_RESEARCH_AUDIT_4SCENARIO/'
e=pd.read_csv(O+'01_ECOLOGICAL_RESULTS/ecological_summary.csv').set_index('skenario')
c=pd.read_csv(O+'03_CARBON_ACCOUNTING/carbon_accounting_A1.csv').set_index('harga')
