SC=['S1','S2','S3','S4USD6','S4USD10','S4USD15','S4USD20','S4USD35']
rows=[]
def add(dom,ind,unit,per,var,vals,ev):
    r=dict(domain=dom,indikator=ind,satuan=unit,periode=per,variabel_sumber=var,klasifikasi_bukti=ev); r.update({k:vals.get(k) for k in SC}); rows.append(r)
g=lambda df,col,ks,div=1:{k:(df.loc[k,col]/div if k in df.index else None) for k in ks}
add('Ekologi','Hutan 2087','ha','2087','Total Hutan',g(e,'hutan_2087_ha',SC),'VERIFIED')
add('Ekologi','Deforestasi kumulatif','ha','2025–2086 (integral DT)','Deforestasi Total',g(e,'deforestasi_kum_2025_2086_ha',SC),'VERIFIED')
add('Ekologi','Regenerasi alami kumulatif','ha','2025–2086','NonHutan menjadi HMS/HRS/HLKS',g(e,'regenerasi_alami_kum_2025_2086_ha',SC),'VERIFIED')
add('Ekologi','Rehabilitasi menjadi hutan kumulatif','ha','2025–2086','Rehabilitasi ke HMS/HRS/HLKS',g(e,'rehabilitasi_menjadi_hutan_kum_2025_2086_ha',SC),'VERIFIED')
add('Ekologi','Deforestasi dihindari vs S1','ha','2025–2086','Deforestasi Total',g(e,'deforestasi_dihindari_vs_S1_ha',SC),'VERIFIED/CONDITIONAL')
add('Ekologi','Selisih stok hutan 2087 vs S1','ha','2087','Total Hutan',g(e,'selisih_hutan_2087_vs_S1_ha',SC),'VERIFIED')
add('Ekologi','Emisi bersih dihindari vs S1','tCO2e','2025–2086','Total Emisi Bersih',g(e,'emisi_dihindari_vs_S1_tCO2e',SC),'VERIFIED/CONDITIONAL')
add('Ekologi','Deforestasi rerata','ha/th','rerata 2030–2055','Deforestasi Total',g(e,'deforestasi_rerata_2030_2055_ha_th',SC),'VERIFIED')
add('Ekologi','Intensitas perlindungan','0–1','rerata 2030–2055','Indeks Intensitas Perlindungan',g(e,'intensitas_perlindungan_rerata_2030_2055',SC),'VERIFIED')
add('Karbon','Kredit REDD diajukan (basis A1)','tCO2e','2024–2086','Kredit REDD Diajukan',g(c,'kredit_REDD_diajukan_tCO2e',SC),'VERIFIED (bukan VCU); CONDITIONAL basis A1')
add('Karbon','Kredit REDD terbit','tCO2e','2024–2086','Kredit REDD Terbit',g(c,'kredit_REDD_terbit_tCO2e',SC),'VERIFIED (bukan VCU)')
add('Karbon','Kredit karbon terjual (REDD+ARR)','tCO2e','2024–2086','Kredit Karbon Terjual',g(c,'kredit_karbon_terjual_total_tCO2e',SC),'VERIFIED (bukan VCU)')
add('Karbon','Porsi kredit dari efek PS (S2−S1)','fraksi','2025–2086','Emisi Deforestasi Biomassa',g(c,'porsi_atribusi_PS',SC),'VERIFIED (diagnostik)')
add('Keuangan','Penerimaan kotor','Rp','2024–2086','Pendapatan Kotor Penjualan Kredit',g(f,'penerimaan_kotor',SC),'VERIFIED')
add('Keuangan','Biaya MRV + transaksi + pajak','Rp','2024–2086','Biaya Transaksi dan MRV',g(f,'biaya_MRV_trans_pajak_total',SC),'VERIFIED')
add('Keuangan','Dana kolektif LPHD diterima','Rp','2024–2086','Dana Desa Diterima',g(f,'dana_LPHD_diterima',SC),'VERIFIED')
add('Keuangan','Dana mitra','Rp','2024–2086','Dana Mitra dari Karbon',g(f,'dana_mitra',SC),'VERIFIED')
add('Keuangan','NPV proyek 10 % (parsial)','Rp','2024–2086','rumus luar model (lihat 04)',g(f,'NPV_proyek_10',SC),'VERIFIED (rekonstruksi)/CONDITIONAL')
add('Keuangan','NPV mitra 10 % (parsial)','Rp','2024–2086','rumus luar model (lihat 04)',g(f,'NPV_mitra_10',SC),'VERIFIED (rekonstruksi)/CONDITIONAL')
add('Kelembagaan','Kebutuhan minimum LPHD','Rp/th','rerata 2030–2055','Kebutuhan Dana Minimum',g(f,'kebutuhan_minimum_rerata_2030_2055',SC),'CONSISTENT (konstruksi model)')
add('Kelembagaan','Belanja LPHD total / kebutuhan minimum (versi naskah)','fraksi','rerata 2030–2055','Penggunaan Dana Pengelolaan',g(f,'cakupan_versi_makalah',SC),'INCONSISTENT sebagai "cakupan"')
add('Kelembagaan','Cakupan berbasis kesenjangan','fraksi','rerata 2030–2055','Kesenjangan Pembiayaan Minimum',g(f,'cakupan_berbasis_kesenjangan',SC),'VERIFIED')
add('Kelembagaan','Belanja komponen minimum / kebutuhan minimum','fraksi','rerata 2030–2055','Realisasi Belanja Operasional+Perlindungan+Kebakaran+Pembiayaan Awal',g(f,'cakupan_komponen_minimum_saja',SC),'VERIFIED (diagnostik audit)')
add('Kelembagaan','Hari patroli didanai','HOK/th','rerata 2030–2055','Hari Patroli Didanai',g(f,'hari_patroli_didanai_rerata',SC),'VERIFIED')
add('Sosial-ekonomi','Kesempatan kerja PS','HOK/th','rerata 2030–2055','Kesempatan Kerja PS',g(s,'HOK_rerata',SC),'VERIFIED')
add('Sosial-ekonomi','Setara pekerja penuh','FTE (HOK/300), bukan orang','rerata 2030–2055','Kesempatan Kerja Setara Penuh',g(s,'FTE_HOK_per_300',SC),'VERIFIED')
add('Sosial-ekonomi','Upah didanai karbon','Rp/th','rerata 2030–2055','Upah Kegiatan Didanai Karbon',g(s,'upah_didanai_karbon_Rp_th',SC),'VERIFIED')
add('Sosial-ekonomi','KUPS aktif','unit','rerata sampel tahunan 2030–2055','Jumlah KUPS Aktif',g(s,'KUPS_aktif_rerata_sampel_tahunan',SC),'VERIFIED/CONDITIONAL (data awal tanpa sumber)')
add('Sosial-ekonomi','Penerimaan anggota KUPS total','Rp/th','rerata 2030–2055','Pendapatan KUPS Total',g(s,'penerimaan_anggota_KUPS_total_Rp_th',SC),'VERIFIED/CONDITIONAL')
add('Sosial-ekonomi','Pendapatan bersih rata-rata RT bergantung','Rp/RT/th (harga 2021)','rerata 2030–2055','Pendapatan Bersih per RT Bergantung',g(s,'pendapatan_bersih_RT_Rp_th',SC),'CONDITIONAL (asumsi akses)')
add('Sosial-ekonomi','Kehilangan akses rata-rata per RT','Rp/RT/th','rerata 2030–2055','Kehilangan Pendapatan Pembatasan Akses per RT',g(s,'kehilangan_akses_per_RT_rata',SC),'CONDITIONAL (asumsi kelas D)')
add('Sosial-ekonomi','Manfaat program per RT','Rp/RT/th','rerata 2030–2055','Pendapatan Program per RT Bergantung',g(s,'pendapatan_program_per_RT',SC),'CONDITIONAL')
pd.DataFrame(rows).to_csv(O+'FINAL_RESULTS_MATRIX.csv',index=False)
